python3 - <<'PY'
import re, glob
rows=[]
for path in sorted(glob.glob('reports/*.md')):
    text=open(path).read()
    wid=re.search(r'# Quarterly site report — (W\d+)', text).group(1)
    m=re.search(r'Region:\s*(\w+)', text)
    if m: region=m.group(1)
    else:
        m=re.search(r'(?:This site sits in the|A)\s+(\w+)[- ]region', text)
        region=m.group(1)
    region=region.strip().capitalize()
    m=re.search(r'Site manager:\s*(.+)', text)
    if m: mgr=m.group(1).strip()
    else:
        m=re.search(r'Managed by\s*(.+)', text)
        if m: mgr=m.group(1).strip()
        else:
            m=re.search(r'(.+?) runs the floor here\.', text)
            mgr=m.group(1).strip()
    mgr=mgr.rstrip('.') if mgr.endswith('..') else mgr
    m=re.search(r'Opened in\s*(\d{4})', text)
    if not m: m=re.search(r'Operating since\s*(\d{4})', text)
    if not m: m=re.search(r'Commissioned\s*(\d{4})', text)
    year=int(m.group(1))
    stock={}
    for line in text.splitlines():
        if line.startswith('- '):
            sk=re.search(r'SKU-([A-Z]\d+)', line)
            if sk:
                clean=re.sub(r'SKU-[A-Z]\d+','',line)
                nums=re.findall(r'\d+', clean)
                assert len(nums)==1, (path,line,clean)
                stock[sk.group(1)]=int(nums[0])
    assert len(stock)==len(set(stock)), path
    rows.append((wid,region,mgr,year,stock))
for r in rows: print(r)
print('N',len(rows))
print('regions', {x:sum(1 for r in rows if r[1]==x) for x in set(r[1] for r in rows)})
